  _o.TARGET_ZONES = this.bb!.createScalarList<string>(this.TARGET_ZONES.bind(this), this.targetZonesLength());
  _o.LANGUAGE = this.LANGUAGE();
  _o.TRANSMITTER_POWER_KW = this.TRANSMITTER_POWER_KW();
  _o.ANTENNA_AZIMUTH_DEG = this.ANTENNA_AZIMUTH_DEG();
